/* Original, bounded CPU reference Transformer. No libraries or downloaded weights. */
(function(root){'use strict';
class Tensor {constructor(r,c,v){this.r=r;this.c=c;this.v=v||new Float64Array(r*c);this.g=new Float64Array(r*c);}}
class HelloTransformer {
 constructor(seed=7){this.seed=seed;this.vocab=['^','$',...new Set('Hello, world!')];this.D=8;this.F=16;this.T=14;this.params=[];this.tape=[];this.step=0;let rng=seed>>>0;const rand=()=>{rng=(Math.imul(rng,1664525)+1013904223)>>>0;return rng/4294967296;};const p=(r,c,scale=.15)=>{const t=new Tensor(r,c);for(let i=0;i<t.v.length;i++)t.v[i]=(rand()*2-1)*scale;t.m=new Float64Array(t.v.length);t.s=new Float64Array(t.v.length);this.params.push(t);return t;};
 this.E=p(this.vocab.length,this.D);this.P=p(this.T,this.D);this.Q=p(this.D,this.D,.3);this.K=p(this.D,this.D,.3);this.V=p(this.D,this.D,.3);this.O=p(this.D,this.D,.3);this.W1=p(this.D,this.F,.3);this.W2=p(this.F,this.D,.3);this.Head=p(this.D,this.vocab.length,.3);
 }
 mm(a,b){const o=new Tensor(a.r,b.c);for(let i=0;i<a.r;i++)for(let k=0;k<a.c;k++)for(let j=0;j<b.c;j++)o.v[i*b.c+j]+=a.v[i*a.c+k]*b.v[k*b.c+j];this.tape.push(()=>{for(let i=0;i<a.r;i++)for(let k=0;k<a.c;k++)for(let j=0;j<b.c;j++){const g=o.g[i*b.c+j];a.g[i*a.c+k]+=g*b.v[k*b.c+j];b.g[k*b.c+j]+=g*a.v[i*a.c+k];}});return o;}
 add(a,b){const o=new Tensor(a.r,a.c);for(let i=0;i<o.v.length;i++)o.v[i]=a.v[i]+b.v[i];this.tape.push(()=>{for(let i=0;i<o.v.length;i++){a.g[i]+=o.g[i];b.g[i]+=o.g[i];}});return o;}
 tanh(a){const o=new Tensor(a.r,a.c);for(let i=0;i<o.v.length;i++)o.v[i]=Math.tanh(a.v[i]);this.tape.push(()=>{for(let i=0;i<o.v.length;i++)a.g[i]+=o.g[i]*(1-o.v[i]*o.v[i]);});return o;}
 embed(ids){const o=new Tensor(ids.length,this.D);for(let i=0;i<ids.length;i++)for(let d=0;d<this.D;d++)o.v[i*this.D+d]=this.E.v[ids[i]*this.D+d]+this.P.v[i*this.D+d];this.tape.push(()=>{for(let i=0;i<ids.length;i++)for(let d=0;d<this.D;d++){this.E.g[ids[i]*this.D+d]+=o.g[i*this.D+d];this.P.g[i*this.D+d]+=o.g[i*this.D+d];}});return o;}
 attention(q,k,v){const n=q.r,d=q.c,scale=1/Math.sqrt(d),p=new Float64Array(n*n),o=new Tensor(n,d);for(let i=0;i<n;i++){let max=-Infinity;for(let j=0;j<=i;j++){let s=0;for(let z=0;z<d;z++)s+=q.v[i*d+z]*k.v[j*d+z];p[i*n+j]=s*scale;max=Math.max(max,p[i*n+j]);}let sum=0;for(let j=0;j<=i;j++)sum+=(p[i*n+j]=Math.exp(p[i*n+j]-max));for(let j=0;j<=i;j++){p[i*n+j]/=sum;for(let z=0;z<d;z++)o.v[i*d+z]+=p[i*n+j]*v.v[j*d+z];}}
 this.tape.push(()=>{for(let i=0;i<n;i++){const dp=new Float64Array(n);let dot=0;for(let j=0;j<=i;j++){for(let z=0;z<d;z++){dp[j]+=o.g[i*d+z]*v.v[j*d+z];v.g[j*d+z]+=p[i*n+j]*o.g[i*d+z];}dot+=p[i*n+j]*dp[j];}for(let j=0;j<=i;j++){const ds=p[i*n+j]*(dp[j]-dot)*scale;for(let z=0;z<d;z++){q.g[i*d+z]+=ds*k.v[j*d+z];k.g[j*d+z]+=ds*q.v[i*d+z];}}}});return o;}
 forward(ids){this.tape=[];const x=this.embed(ids),a=this.attention(this.mm(x,this.Q),this.mm(x,this.K),this.mm(x,this.V)),h=this.add(x,this.mm(a,this.O)),f=this.tanh(this.mm(h,this.W1)),y=this.add(h,this.mm(f,this.W2));return this.mm(y,this.Head);}
 loss(backward=false){const target=[...'Hello, world!','$'].map(c=>this.vocab.indexOf(c)),ids=[0,...target.slice(0,-1)],logits=this.forward(ids);let loss=0;for(let i=0;i<ids.length;i++){const row=Array.from(logits.v.slice(i*logits.c,(i+1)*logits.c)),m=Math.max(...row),e=row.map(x=>Math.exp(x-m)),sum=e.reduce((a,b)=>a+b,0);loss+=Math.log(sum)+m-row[target[i]];if(backward)for(let j=0;j<logits.c;j++)logits.g[i*logits.c+j]=(e[j]/sum-(j===target[i]?1:0))/ids.length;}if(backward)for(let i=this.tape.length-1;i>=0;i--)this.tape[i]();return loss/ids.length;}
 train(){for(const p of this.params)p.g.fill(0);const loss=this.loss(true);this.step++;let norm=0;for(const p of this.params)for(const g of p.g)norm+=g*g;const clip=Math.min(1,5/Math.sqrt(norm||1)),b1=1-Math.pow(.9,this.step),b2=1-Math.pow(.999,this.step);for(const p of this.params)for(let i=0;i<p.v.length;i++){const g=p.g[i]*clip;p.m[i]=.9*p.m[i]+.1*g;p.s[i]=.999*p.s[i]+.001*g*g;p.v[i]-=.02*(p.m[i]/b1)/(Math.sqrt(p.s[i]/b2)+1e-8);}return loss;}
 generate(){const ids=[0];let out='';for(let t=0;t<this.T;t++){const logits=this.forward(ids),offset=(ids.length-1)*logits.c;let best=0;for(let j=1;j<logits.c;j++)if(logits.v[offset+j]>logits.v[offset+best])best=j;const token=this.vocab[best];if(token==='$')break;out+=token;ids.push(best);}return out;}
 checkpoint(){return {format:'familiar-tiny-transformer-v1',seed:this.seed,steps:this.step,dimensions:this.D,feedforward:this.F,vocab:this.vocab,trainingText:'Hello, world!',weights:this.params.map(p=>({rows:p.r,cols:p.c,values:Array.from(p.v)}))};}
}
if(typeof module!=='undefined'&&module.exports)module.exports={HelloTransformer};else root.HelloTransformer=HelloTransformer;
})(typeof self!=='undefined'?self:this);
